modern_c2_q7.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    people_patches = image_patch.find("person")
    hat_patches = image_patch.find("hat")
    bat_patches = image_patch.find("bat")

    if not people_patches or not hat_patches or not bat_patches:
        return image_patch

    person_hat_pairs = [(p, h) for p in people_patches for h in hat_patches if p.overlaps_with(h.left, h.lower, h.right, h.upper)]
    person_hat_bat_triples = [(p, h, b) for p, h in person_hat_pairs for b in bat_patches if p.overlaps_with(b.left, b.lower, b.right, b.upper)]

    if not person_hat_bat_triples:
        return image_patch

    swinging_persons = []
    for p, h, b in person_hat_bat_triples:
        if b.left < p.left < b.right and abs(p.vertical_center - h.vertical_center) < 20:
            swinging_persons.append((p, h, b))

    if not swinging_persons:
        return image_patch

    swinging_persons.sort(key=lambda x: x[2].horizontal_center)
    return swinging_persons[-1][0]

